import{calculator,CalcError,num,has,ceilSafe,dflt}from './core.js?ver=8339faab16';import{fmt}from './format.js?ver=8339faab16';import{home_plan}from './planner.js?ver=8339faab16';import{standbyFor}from './backup.js?ver=8339faab16';import{priceRange,inverterAt}from './prices.js?ver=8339faab16';import{bill_total}from './bill.js?ver=8339faab16';const mid=(r)=>(r.low+r.high)/2;const rs=(v)=>fmt(v,'rs');const net=(v)=>(v>=0?`${rs(v)} cost`:`${rs(-v)} saved`);const SB=[['standby','UPS or generator'],['combo','On-grid solar + UPS or generator']];const weak=(r)=>(r.n_sources??0)<2;
export const home_decision=calculator((i,d)=>{const p=home_plan.raw(i,d);const cp=d?.component_prices?.items;const bp=d?.backup_prices;if(!cp||!bp?.lithium_pack)throw new CalcError('price_data_missing','loads');if(p.backup_hours>24)throw new CalcError('backup_hours_too_large','backup_hours');const years=num(i,'years',{def:dflt(d,'decision_years'),gt:0,max:30});const budget=has(i,'budget_rs')?num(i,'budget_rs',{gt:0}):0;const months=years*12;const need=p.backup_hours>0;const W=fmt(p.backup_w,'int');const hours=`${fmt(p.backup_hours,'1')} h of ${W} W`;const kw=p.installed_kw;const pr=priceRange(d,'on-grid',kw);const out={...p,years,budget_rs:budget,low_confidence:pr.low_confidence};const setups=[];const add=(id,key,option,low,high,repl,saving,running,backup,ok=true)=>{const s={key,option,low,high,buy:(low+high)/2,repl,saving,running,backup,ok};s.net_rs=s.buy+repl+months*(running-saving);s.net=ok?net(s.net_rs):'Not counted';s.price=ok?`${rs(low)} to ${rs(high)}`:backup;setups.push(s);Object.assign(out,{[`${id}_option`]:option,[`${id}_low_rs`]:low,[`${id}_high_rs`]:high,[`${id}_rs`]:s.buy,[`${id}_repl_rs`]:repl,[`${id}_running_rs`]:running,[`${id}_net`]:ok?s.net:'not counted',[`${id}_available`]:ok});return s;};const og=[pr.lo*kw*1000,pr.hi*kw*1000];const o=add('ongrid','ongrid',`On-grid solar ${fmt(kw,'2')} kW`,...og,0,p.full_saving_rs,0,'None: switches off in a power cut');const lines=[`${o.option}, installed: ${o.price}, saves ${rs(o.saving)} a month, no backup in a cut, net ${o.net}.`];if(need){const li=p.chemistry==='lifepo4';const t=bp.tubular_unit;const bank_v=dflt(d,'hybrid_bank_v');const units=li?ceilSafe(p.battery_kwh/bp.lithium_pack.kwh):ceilSafe((p.battery_kwh*1000)/(bank_v*t.ah))*ceilSafe(bank_v/t.v);const item=cp.find((x)=>(li?x.category==='lithium_battery'&&x.size===bp.lithium_pack.size:x.category==='tubular_battery'));if(!item)throw new CalcError('price_data_missing','chemistry');const s=units>1;const battery=li?`${units} lithium pack${s?'s':''} of ${fmt(bp.lithium_pack.kwh,'2')} kWh (51.2 V)`:`${units} tubular batter${s?'ies':'y'} of ${t.v} V ${t.ah} Ah (${bank_v} V bank)`;const hkw=Math.max(p.inverter_kw,(p.backup_w*p.margin)/1000);const[hy,hw,above]=inverterAt(cp,'hybrid_inverter',hkw);const[on,ow]=inverterAt(cp,'ongrid_inverter',p.inverter_kw);const premium=Math.max(0,hy-on);const repl=Math.max(0,Math.floor((years-1e-9)/bp.battery_life_years[p.chemistry]));const bat=units*mid(item);const h=add('hybrid','hybrid',`Hybrid solar ${fmt(kw,'2')} kW + ${battery}`,og[0]+premium+units*item.low,og[1]+premium+units*item.high,repl*bat,p.full_saving_rs,0,`${hours} from the battery`);lines.push(`${h.option}: ${h.price} (the on-grid price plus ${rs(bat)} of battery and ${rs(premium)} extra for a ${fmt(hkw,'up1')} kW grid-tie hybrid inverter${above?' (above our list: rough)':''}), battery replacements ${rs(repl*bat)}, net ${h.net}.`);Object.assign(out,{hybrid_battery:battery,hybrid_battery_units:units,hybrid_battery_rs:bat,hybrid_inverter_kw:hkw,hybrid_premium_rs:premium,hybrid_replacements:repl,low_confidence:out.low_confidence||hw||ow||weak(item)});const bin={load_w:p.backup_w,hours:p.backup_hours,years,tariff:p.rate_before,city:i.city,panel_w:p.panel_w};const bt=(units)=>bill_total.raw({sanctioned_kw:p.sanctioned_kw,protected:false,units},d).total_rs;const sb=standbyFor(bin,d,(r)=>bt(p.monthly_units+r)-p.full_before_rs);if(sb){const{u}=sb;const b=add('standby',sb.key,sb.option,sb.lo,sb.hi,sb.repl,0,sb.run,u?hours:'As long as there is petrol');lines.push(`${b.option} for ${W} W: ${b.price}, ${u?`grid recharge adds ${rs(b.running)} a month to the bill`:`petrol and oil cost ${rs(b.running)} a month`}, net ${b.net}.`);const cs=u?p.full_before_rs-Math.max(0,bt(p.import_units+sb.r)-p.export_credit_rs):p.full_saving_rs;const c=add('combo','combo',`${o.option} + ${b.option}`,og[0]+sb.lo,og[1]+sb.hi,sb.repl,Math.max(0,cs),(u?0:sb.run)+Math.max(0,-cs),b.backup);lines.push(`${c.option}: ${c.price}, saves ${rs(c.saving)} a month${u?(c.running?`, the recharge adds ${rs(c.running)} a month`:' with the recharge on the bill'):` and burns ${rs(c.running)} of petrol and oil`}, net ${c.net}.`);}else{for(const[id,name]of SB)add(id,id,name,0,0,0,0,0,'Not available for this backup load',false);lines.push(`A UPS or generator for ${W} W is above our price lists.`);}}else{for(const[id,name]of[['hybrid','Hybrid solar + battery'],...SB])add(id,id,name,0,0,0,0,0,'Not needed without backup hours',false);lines.push('The setups with backup need backup hours.');}
const grid={key:'grid',option:'Stay on the grid (no purchase)',low:0,high:0,buy:0,saving:0,running:0,backup:'None',net:rs(0),net_rs:0,price:rs(0)};const pool=need?setups.filter((x)=>x.ok&&x !==o):[o,grid];const fits=pool.filter((x)=>!budget||x.buy<=budget+1e-9);const over=pool.length>0&&!fits.length;const pick=fits.length?fits.reduce((a,b)=>(b.net_rs<a.net_rs-1e-9||(Math.abs(b.net_rs-a.net_rs)<=1e-9&&b.buy<a.buy)?b:a)):pool.length?pool.reduce((a,b)=>(b.buy<a.buy?b:a)):{...grid,key:'none',option:'No setup in our price lists fits this backup load'};const gap=over?pick.buy-budget:0;return Object.assign(out,{setups:setups.map((x)=>({option:x===pick?`${x.option} (recommended)`:x.option,price:x.price,backup:x.backup,saving_month:x.saving,running_month:x.running,net:x.net})),decision_key:pick.key,decision:over?`${pick.option} (over your budget by ${rs(gap)})`:pick.option,decision_text:[...lines,pick.key==='none'?`${pick.option}.`:over?`Nothing with your backup fits your budget; cheapest: ${pick.option}, ${rs(gap)} over it.`:`Recommended, the lowest net ${need?'that gives your backup':'of on-grid solar and staying on the grid'}${budget?' within your budget':''}: ${pick.option}.`].join(' '),decision_rs:pick.buy,decision_price:pick.price,decision_saving_rs:pick.saving,decision_running_rs:pick.running,decision_backup:pick.backup,decision_net:pick.net,over_budget:over,budget_gap_rs:gap,});});
